package com.smartfix.communityapp;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.TransactionDefinition;
import com.fasterxml.jackson.databind.ObjectMapper;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
@EnabledIfEnvironmentVariable(named="STAGE4_POSTGRES",matches="true")
class PostingPostgresTest {
 @Test void concurrentFirstPostingDuplicateAndSeparateQuotasAreAtomic()throws Exception{
  var secrets=new ObjectMapper().readTree(Files.readString(Path.of(System.getProperty("smartfix.test.runtime"),"credentials-private.json")));var ds=new DriverManagerDataSource("jdbc:postgresql://127.0.0.1:15453/smartfix_migration_community","sf_migration_community",secrets.get("community").asText());var db=new JdbcTemplate(ds);var guard=new CommunityPostingGuard(db);var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);long a=800000000000L+new Random().nextInt(1000000),b=a+1000001;var pool=Executors.newFixedThreadPool(8);
  try{
   AtomicInteger accepted=new AtomicInteger();List<Callable<Void>> jobs=new ArrayList<>();
   for(int i=0;i<12;i++)jobs.add(()->{try{tx.execute(s->guard.question(a,"Concurrent duplicate title","Concurrent duplicate body content",()->db.update("INSERT INTO community_questions(author_id,title,body,category) VALUES (?,? ,?,'OTHER')",a,"Concurrent duplicate title","Concurrent duplicate body content")));accepted.incrementAndGet();}catch(org.springframework.web.server.ResponseStatusException expected){assertEquals(400,expected.getStatusCode().value());}return null;});
   for(var future:pool.invokeAll(jobs))future.get();assertEquals(1,accepted.get());assertEquals(1,db.queryForObject("SELECT count(*) FROM community_posting_guards WHERE user_id=?",Integer.class,a));
   accepted.set(0);jobs.clear();for(int i=0;i<24;i++){final int index=i;jobs.add(()->{try{tx.execute(s->guard.question(b,"Unique question "+index,"Unique body content "+index,()->db.update("INSERT INTO community_questions(author_id,title,body,category) VALUES (?,? ,?,'OTHER')",b,"Unique question "+index,"Unique body content "+index)));accepted.incrementAndGet();}catch(org.springframework.web.server.ResponseStatusException expected){assertEquals(400,expected.getStatusCode().value());}return null;});}for(var future:pool.invokeAll(jobs))future.get();assertEquals(20,accepted.get());
   long question=db.queryForObject("SELECT id FROM community_questions WHERE author_id=? LIMIT 1",Long.class,a);accepted.set(0);jobs.clear();for(int i=0;i<24;i++)jobs.add(()->{try{tx.execute(s->guard.answer(a,()->db.update("INSERT INTO community_answers(question_id,author_id,body) VALUES (?,?,'Concurrency verification answer')",question,a)));accepted.incrementAndGet();}catch(org.springframework.web.server.ResponseStatusException expected){assertEquals(400,expected.getStatusCode().value());}return null;});for(var future:pool.invokeAll(jobs))future.get();assertEquals(20,accepted.get());
  }finally{pool.shutdownNow();db.update("DELETE FROM community_answers WHERE author_id IN (?,?)",a,b);db.update("DELETE FROM community_questions WHERE author_id IN (?,?)",a,b);db.update("DELETE FROM community_posting_guards WHERE user_id IN (?,?)",a,b);}
 }
}
